"""Render docs/CATALOG.md from catalog/catalog.json. Run with --check in CI to catch drift."""
import json
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = os.path.join(ROOT, "catalog", "catalog.json")
OUT = os.path.join(ROOT, "docs", "CATALOG.md")


def cell(text):
    return str(text).replace("|", "\\|").replace("\n", " ")


def render(data):
    lines = [
        "# Catalog",
        "",
        "<!-- Generated by scripts/render_catalog.py from catalog/catalog.json. Do not edit by hand. -->",
        "",
        "Reviewed %s. %s" % (data["reviewed"], data["rubric"]["note"]),
        "",
        "| Rating | Meaning |",
        "| --- | --- |",
    ]
    for scale, meaning in data["rubric"]["scale"].items():
        lines.append("| %s | %s |" % (scale, meaning))
    lines += ["", "| Item | Kind | License | Rating | Risk | What it does | Effect on a project | Activation rules |", "| --- | --- | --- | --- | --- | --- | --- | --- |"]
    for item in sorted(data["items"], key=lambda i: (-(i["rating"] or 0), i["name"])):
        rating = "n/a" if item["rating"] is None else str(item["rating"])
        lines.append("| [%s](%s) | %s | %s | %s | %s | %s | %s | %s |" % (
            cell(item["name"]), item["upstream"], item["kind"], cell(item["license"]), rating, item["risk"],
            cell(item["what"]), cell(item["impact"]), cell(item["activation"])))
    lines += ["", "## Rating notes", ""]
    for item in sorted(data["items"], key=lambda i: (-(i["rating"] or 0), i["name"])):
        lines.append("- **%s** (%s): %s" % (item["name"], "n/a" if item["rating"] is None else item["rating"], item["rating_note"]))
    return "\n".join(lines) + "\n"


def main(argv):
    with open(SRC, "r", encoding="utf-8") as handle:
        text = render(json.load(handle))
    if "--check" in argv:
        current = open(OUT, "r", encoding="utf-8", newline="").read().replace("\r\n", "\n") if os.path.isfile(OUT) else ""
        if current != text:
            print("docs/CATALOG.md is out of date: run python scripts/render_catalog.py")
            return 1
        print("docs/CATALOG.md is up to date")
        return 0
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w", encoding="utf-8", newline="\n") as handle:
        handle.write(text)
    print("wrote", OUT)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
